import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Skill Triggers","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/mobs/triggers.md","filePath":"en/modules/mobs/triggers.md","lastUpdated":0}`),a={name:`en/modules/mobs/triggers.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="skill-triggers" tabindex="-1">Skill Triggers <a class="header-anchor" href="#skill-triggers" aria-label="Permalink to “Skill Triggers”">​</a></h1><p>The <code>actions</code> section in a mob definition binds lifecycle trigger events to CoreLib action pipelines. Action lines are executed by the <strong>EmakiCoreLib</strong> action pipeline (a hard dependency), so installing EmakiSkills is <strong>not</strong> required. The legacy <code>skills</code> key remains as a compatibility fallback and logs a WARN when read; migrating is recommended.</p><h2 id="trigger-list" tabindex="-1">Trigger list <a class="header-anchor" href="#trigger-list" aria-label="Permalink to “Trigger list”">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>When it fires</th><th>Context objects</th></tr></thead><tbody><tr><td><code>on_spawn</code></td><td>Mob spawned (inside <code>MobFactory</code>, right after the boss bar and model attach)</td><td>—</td></tr><tr><td><code>on_death</code></td><td>Mob dies</td><td><code>killer</code> (only when a living killer exists)</td></tr><tr><td><code>on_target</code></td><td>Mob acquires a new target</td><td><code>target</code> (only when the target is non-null)</td></tr><tr><td><code>on_damage_give</code></td><td>This mob deals damage as the attacker</td><td><code>target</code> (only when the victim is a living entity)</td></tr><tr><td><code>on_damage_take</code></td><td>This mob takes damage</td><td><code>attacker</code> (only when the damager is a living entity)</td></tr><tr><td><code>on_kill</code></td><td>Mob kills an entity</td><td><code>victim</code> (the killed entity)</td></tr><tr><td><code>on_shoot</code></td><td>Mob fires a projectile</td><td>—</td></tr><tr><td><code>on_explode</code></td><td>Mob explodes (e.g. Creeper)</td><td>—</td></tr><tr><td><code>on_teleport</code></td><td>Mob teleports</td><td>—</td></tr><tr><td><code>on_transform</code></td><td>Mob transforms (e.g. zombie → drowned)</td><td>—</td></tr><tr><td><code>on_health_threshold_&lt;percent&gt;</code></td><td>Mob health first drops to or below that percentage</td><td>—</td></tr></tbody></table><p>The objects listed under &quot;Context objects&quot; are supplied by EmakiMobs through CoreLib action context keys. When one is absent, the matching source (such as <code>killer</code>) resolves to nothing and that action line is not executed. There is <strong>no damage-amount object</strong> — neither <code>on_damage_give</code> nor <code>on_damage_take</code> provides <code>damage</code>; use another CoreLib mechanism when you need the amount.</p><h3 id="health-threshold-triggers" tabindex="-1">Health threshold triggers <a class="header-anchor" href="#health-threshold-triggers" aria-label="Permalink to “Health threshold triggers”">​</a></h3><p><code>on_health_threshold_&lt;percent&gt;</code> uses a fixed set of five tiers; only these five key names fire:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>on_health_threshold_90</span></span>
<span class="line"><span>on_health_threshold_75</span></span>
<span class="line"><span>on_health_threshold_50</span></span>
<span class="line"><span>on_health_threshold_25</span></span>
<span class="line"><span>on_health_threshold_10</span></span></code></pre></div><p>Other numbers (such as <code>on_health_threshold_80</code>) raise no error but never fire.</p><p>Each tier fires <strong>only once</strong> per mob. When a mob takes damage, the tiers are checked from 90 down to 10; if a single hit crosses several tiers, each crossed tier fires in sequence during that same hit. The percentage is computed as <code>current health / max-health attribute value</code>, and no threshold check runs when that attribute is missing or non-positive.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Health thresholds are checked together with the damage event, so <code>on_damage_take</code> and any crossed threshold trigger run at the same time.</p></div><h2 id="action-string-format" tabindex="-1">Action string format <a class="header-anchor" href="#action-string-format" aria-label="Permalink to “Action string format”">​</a></h2><p>Each trigger maps to a list of CoreLib action pipeline strings:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[selector |] action_name [key=value ...]</span></span></code></pre></div><h3 id="common-selectors" tabindex="-1">Common selectors <a class="header-anchor" href="#common-selectors" aria-label="Permalink to “Common selectors”">​</a></h3><table tabindex="0"><thead><tr><th>Selector</th><th>Provided by</th><th>Description</th></tr></thead><tbody><tr><td><code>self</code></td><td>CoreLib</td><td>The mob that fired the event (the pipeline caster).</td></tr><tr><td><code>target</code></td><td>EmakiMobs</td><td>The current event&#39;s target entity (<code>on_target</code>, <code>on_damage_give</code>).</td></tr><tr><td><code>killer</code></td><td>EmakiMobs</td><td>The entity that killed the mob (<code>on_death</code>).</td></tr><tr><td><code>victim</code></td><td>EmakiMobs</td><td>The entity killed by the mob (<code>on_kill</code>).</td></tr><tr><td><code>attacker</code></td><td>EmakiMobs</td><td>The entity that damaged the mob (<code>on_damage_take</code>).</td></tr><tr><td><code>nearby radius=&lt;n&gt; include_players=true</code></td><td>CoreLib</td><td>Entities within the radius. <strong>Players are excluded by default</strong>: <code>include_players</code> defaults to <code>false</code>, so writing only <code>type=player</code> selects nobody — add <code>include_players=true</code> explicitly.</td></tr></tbody></table><p>The four EmakiMobs-provided selectors (<code>target</code> / <code>killer</code> / <code>victim</code> / <code>attacker</code>) depend on the context objects listed above and can only resolve a target when that object exists in the trigger&#39;s event.</p><h3 id="action-examples" tabindex="-1">Action examples <a class="header-anchor" href="#action-examples" aria-label="Permalink to “Action examples”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_spawn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Send a message to all players within 20 blocks</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nearby radius=20 include_players=true | send_message text=&#39;&lt;red&gt;Elite Zombie has arrived!&#39;&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Spawn particles at the mob&#39;s location</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | spawn_particle particle=FLAME count=30 offset_x=0 offset_y=1 offset_z=0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_death</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Give experience to the killer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;killer | give_exp amount=80&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Broadcast defeat message to nearby players</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nearby radius=50 include_players=true | send_message text=&#39;&lt;green&gt;Elite Zombie defeated!&#39;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_give</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Apply slowness to the target</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target | give_potion_effect type=SLOWNESS level=1 duration=3s&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_take</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Spawn flame particles when hurt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | spawn_particle particle=FLAME count=10 offset_x=0 offset_y=1 offset_z=0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Play a sound when acquiring a target</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | play_sound sound=minecraft:entity.skeleton.ambient volume=1.0 pitch=0.7&quot;</span></span></code></pre></div><h2 id="sources-and-stages-registered-by-emakimobs" tabindex="-1">Sources and stages registered by EmakiMobs <a class="header-anchor" href="#sources-and-stages-registered-by-emakimobs" aria-label="Permalink to “Sources and stages registered by EmakiMobs”">​</a></h2><p>Besides CoreLib&#39;s built-in content, EmakiMobs registers 8 segments with the action system (the startup log prints the registered count against an expected 8): four sources <code>attacker</code> / <code>killer</code> / <code>victim</code> / <code>target</code>, and four stages <code>summon_mob</code> / <code>mob_play_animation</code> / <code>mob_stop_animation</code> / <code>mob_set_model</code>. When an action line fails to compile, the console prints <code>技能编译错误: mob=&lt;id&gt; trigger=&lt;trigger&gt; line=&lt;line&gt; reason=&lt;reason&gt;</code>; that line is skipped and the other lines of the same trigger still run.</p><h3 id="summon-mob-—-summon-a-mob-definition" tabindex="-1"><code>summon_mob</code> — summon a mob definition <a class="header-anchor" href="#summon-mob-—-summon-a-mob-definition" aria-label="Permalink to “summon_mob — summon a mob definition”">​</a></h3><p>Summons an EmakiMobs mob definition at the target&#39;s location.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Accepted values</th><th>Description</th></tr></thead><tbody><tr><td><code>mob_id</code></td><td>string</td><td>Yes</td><td>none</td><td>a loaded mob definition id (case-sensitive)</td><td>Definition to summon; a missing or blank value returns a configuration error (<code>INVALID_CONFIG</code>), and an unregistered id returns the same.</td></tr><tr><td><code>count</code></td><td>int</td><td>No</td><td><code>1</code></td><td><code>≥ 1</code> (below 1 is treated as 1)</td><td>Number to summon; spawned one by one at the target location.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_damage_take</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Summon two fire guardians at the mob&#39;s own location</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;self | summon_mob mob_id=fire_guardian count=2&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  on_health_threshold_50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # At half health, summon one minion at the killer&#39;s location</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;killer | summon_mob mob_id=boss_minion&quot;</span></span></code></pre></div><p>The action needs a resolvable location from the target (its execution domain is the location region). With no location it returns <code>skipped</code>; when every summon fails it returns <code>INTERNAL_ERROR</code>.</p><h3 id="model-stages" tabindex="-1">Model stages <a class="header-anchor" href="#model-stages" aria-label="Permalink to “Model stages”">​</a></h3><p>The parameters and behaviour of <code>mob_play_animation</code>, <code>mob_stop_animation</code>, and <code>mob_set_model</code> are documented in the &quot;Action stages&quot; section of <a href="./models.html">Entity Models &amp; Animations</a>.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>The full list of available actions and their parameter syntax is provided by <strong>EmakiCoreLib</strong>. Refer to the CoreLib documentation for all supported actions.</p></div>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};